args.sql:
SELECT acct_bridge, "NetInfl", "CoordScore" FROM (
    SELECT ac.acct_bridge, cl."NetInfl", cl."CoordScore",
           ROW_NUMBER() OVER (PARTITION BY ac.acct_bridge ORDER BY cl."CLSTR_PIN") as rn
    FROM account_clusters ac
    JOIN cluster_analysis cl ON cl."CLSTR_PIN" = ac.clu_ref
) sub WHERE rn = 1 LIMIT 5;

